"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant1 from "./components/notification-center/variants/02-panel";
const variants = {"panel": Variant1};
export interface ArtemisNotificationCenterProps { className?: string; variant?: "panel"; }
export function ArtemisNotificationCenter({ className, variant = "panel" }: ArtemisNotificationCenterProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { RotateCcw } from "lucide-react";
import { useCallback, useMemo, useState } from "react";
import { PanelButton as ArtemisButton } from "./02-panel/panel-button";
import { INITIAL_ITEMS, type NotificationItem, PANEL_FILTERS } from "./02-panel/data";
import { ArtemisMorphicTooltip } from "./02-panel/morphic-tooltip";
import { NotificationPanel } from "./02-panel/notification-panel";
export default function NotificationCenterPanel() {
    const [items, setItems] = useState<readonly NotificationItem[]>(INITIAL_ITEMS);
    const [message, setMessage] = useState("");
    const [query, setQuery] = useState("");
    const remove = useCallback((item: NotificationItem, action: string) => {
        setItems((current) => current.filter((entry) => entry.id !== item.id));
        setMessage(`${action}: ${item.title}`);
    }, []);
    const handlers = useMemo(() => ({
        onReadChange: (item: NotificationItem, read: boolean) => setItems((current) => current.map((entry) => (entry.id === item.id ? { ...entry, read } : entry))),
        onMarkAllRead: () => {
            setItems((current) => current.map((entry) => ({ ...entry, read: true })));
            setMessage("All updates marked as read.");
        },
        onSnooze: (item: NotificationItem) => remove(item, "Snoozed in this demo"),
        onArchive: (item: NotificationItem) => remove(item, "Archived"),
        onSelect: (item: NotificationItem) => {
            setItems((current) => current.map((entry) => (entry.id === item.id ? { ...entry, read: true } : entry)));
            setMessage(`Opened: ${item.title}`);
        },
    }), [remove]);
    return (<>
      <NotificationPanel items={items} query={query} onQueryChange={setQuery} filters={PANEL_FILTERS} handlers={handlers} headerActions={<ArtemisMorphicTooltip content="Reset demo">
            <ArtemisButton variant="ghost" size="icon" className="art:size-9 art:rounded-full art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring" aria-label="Reset demo" onClick={() => {
                setItems(INITIAL_ITEMS);
                setMessage("");
                setQuery("");
            }}>
              <RotateCcw aria-hidden className="art:size-3.5"/>
            </ArtemisButton>
          </ArtemisMorphicTooltip>} footer={<div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-2">
            <output>{message || "Updates across your workspace"}</output>
            <span className="art:shrink-0 art:tabular-nums">{items.length} updates</span>
          </div>}/>
    </>);
}

// @zeus-internal
