        id: "export",
        title: "Your export is ready",
        description: "The latest project files are ready to download.",
        time: "8m ago",
        category: "system",
        read: false,
        icon: "download",
    },
    {
        id: "invite",
        title: "Invitation needs approval",
        description: "Jordan requested access to the design workspace.",
        time: "12m ago",
        category: "action",
        read: false,
        avatarUrl: "/assets/artemis/83b960a1aaa67c851088.svg",
        actionLabel: "View request",
    },
    {
        id: "comment",
