"use client";
// @zeus-internal
import { AnimatePresence, animate, motion, useMotionValue, type Variants } from "motion/react";
import { createContext, type ReactNode, useCallback, useContext, useEffect, useId, useMemo, useRef, useState } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
const OPEN_DELAY = 180;
const CLOSE_DELAY = 80;
const GAP = 10;
const VIEWPORT_PADDING = 12;
const ESTIMATED_HEIGHT = 30;
const MORPH_POSITION = { type: "spring", stiffness: 181, damping: 21 } as const;
const MORPH_SIZE = { type: "spring", stiffness: 161, damping: 18.3 } as const;
const FADE = { duration: 0.15, ease: ARTEMIS_EASE_OUT } as const;
const INSTANT = { duration: 0 } as const;
type Shown = {
    key: string;
    anchor: HTMLElement;
    content: string;
    instant: boolean;
};
type TooltipApi = {
    enter: (key: string, anchor: HTMLElement, content: string) => void;
    leave: (key: string) => void;
    down: (key: string) => void;
    focus: (key: string, anchor: HTMLElement, content: string) => void;
    blur: (key: string) => void;
    hide: (key: string) => void;
};
const TooltipContext = createContext<TooltipApi | null>(null);
const ROOT_VARIANTS: Variants = {
    hidden: (instant: boolean) => ({ opacity: 0, transition: instant ? INSTANT : FADE }),
    shown: { opacity: 1, transition: FADE },
};
const TEXT_VARIANTS: Variants = {
    hidden: (instant: boolean) => ({
        opacity: 0,
        y: 3,
        transition: instant
            ? INSTANT
            : { opacity: { duration: 0.14, ease: ARTEMIS_EASE_OUT }, y: { type: "spring", stiffness: 360, damping: 28, mass: 0.8 } },
    }),
    shown: { opacity: 1, y: 0 },
};
function anchorPoint(anchor: HTMLElement) {
    const rect = anchor.getBoundingClientRect();
    return { x: rect.left + rect.width / 2, top: rect.top };
}
function clampX(x: number, width: number) {
    const min = VIEWPORT_PADDING + width / 2;
    const max = window.innerWidth - VIEWPORT_PADDING - width / 2;
    return max < min ? window.innerWidth / 2 : Math.min(Math.max(x, min), max);
}
function Bubble({ shown }: {
    shown: Shown;
}) {
    const contentRef = useRef<HTMLDivElement>(null);
    const last = useRef<{
        anchor: HTMLElement;
        content: string;
    } | null>(null);
    const start = useMemo(() => anchorPoint(shown.anchor), [shown.anchor]);
    const x = useMotionValue(start.x);
    const y = useMotionValue(start.top - GAP - ESTIMATED_HEIGHT);
    const width = useMotionValue(0);
    const height = useMotionValue(0);
    useEffect(() => {
        const el = contentRef.current;
        if (!el)
            return;
        const rect = el.getBoundingClientRect();
        const w = Math.ceil(rect.width);
        const h = Math.ceil(rect.height);
        const point = anchorPoint(shown.anchor);
        const prev = last.current;
        last.current = { anchor: shown.anchor, content: shown.content };
        const targetX = clampX(point.x, w);
        if (!prev || (prev.anchor === shown.anchor && prev.content === shown.content)) {
            x.set(targetX);
            y.set(point.top - GAP - h);
            width.set(w);
            height.set(h);
            return;
        }
        const controls = [
            animate(x, targetX, MORPH_POSITION),
            animate(y, point.top - GAP - h, MORPH_POSITION),
            animate(width, w, MORPH_SIZE),
            animate(height, h, MORPH_SIZE),
        ];
        return () => {
            for (const c of controls)
                c.stop();
        };
    }, [shown.anchor, shown.content, x, y, width, height]);
    return (<motion.div aria-hidden="true" className="art:pointer-events-none art:fixed art:top-0 art:left-0 art:z-[2147483647]" style={{ x, y }} variants={ROOT_VARIANTS} initial={shown.instant ? false : "hidden"} animate="shown" exit="hidden">
      <div style={{ transform: "translateX(-50%)", willChange: "transform" }}>
        <motion.div className="art:relative art:overflow-hidden art:rounded-xl art:border art:border-background/15 art:bg-foreground art:text-background" style={{ transformOrigin: "center bottom", willChange: "width, height, transform", width, height }} initial={false} animate={{ opacity: 1, scale: 1 }}>
          <div ref={contentRef} className="art:absolute art:top-1/2 art:left-1/2 art:w-max art:max-w-[min(18rem,calc(100vw-24px))] art:-translate-x-1/2 art:-translate-y-1/2 art:px-2 art:py-2 art:text-center art:text-xs">
            <motion.div variants={TEXT_VARIANTS} initial={false} animate="shown" exit="hidden">
              {shown.content}
            </motion.div>
          </div>
        </motion.div>
      </div>
    </motion.div>);
}
export function ArtemisMorphicTooltipProvider({ children }: {
    children: ReactNode;
}) {
    const [shown, setShown] = useState<Shown | null>(null);
    const [exitInstant, setExitInstant] = useState(false);
    const [mounted, setMounted] = useState(false);
    const shownRef = useRef<Shown | null>(null);
    const openTimer = useRef<number | undefined>(undefined);
    const closeTimer = useRef<number | undefined>(undefined);
    const suppressed = useRef(new Set<string>());
    useEffect(() => {
        setMounted(true);
        return () => {
            window.clearTimeout(openTimer.current);
            window.clearTimeout(closeTimer.current);
        };
    }, []);
    const api = useMemo<TooltipApi>(() => {
        const show = (next: Shown | null, instantExit = false) => {
            shownRef.current = next;
            if (!next)
                setExitInstant(instantExit);
            setShown(next);
        };
        const clearTimers = () => {
            window.clearTimeout(openTimer.current);
            window.clearTimeout(closeTimer.current);
        };
        const scheduleClose = (key: string, instant: boolean) => {
            window.clearTimeout(openTimer.current);
            if (shownRef.current?.key !== key)
                return;
            window.clearTimeout(closeTimer.current);
            closeTimer.current = window.setTimeout(() => show(null, instant), CLOSE_DELAY);
        };
        return {
            enter(key, anchor, content) {
                if (suppressed.current.has(key))
                    return;
                clearTimers();
                const current = shownRef.current;
                if (current) {
                    if (current.key !== key)
                        show({ key, anchor, content, instant: current.instant });
                    return;
                }
                openTimer.current = window.setTimeout(() => show({ key, anchor, content, instant: false }), OPEN_DELAY);
            },
            leave(key) {
                suppressed.current.delete(key);
                scheduleClose(key, false);
            },
            down(key) {
                suppressed.current.add(key);
                scheduleClose(key, false);
            },
            focus(key, anchor, content) {
                clearTimers();
                const current = shownRef.current;
                if (current?.key === key)
                    return;
                show({ key, anchor, content, instant: current ? current.instant : true });
            },
            blur(key) {
                scheduleClose(key, true);
            },
            hide(key) {
                window.clearTimeout(openTimer.current);
                if (shownRef.current?.key !== key)
                    return;
                window.clearTimeout(closeTimer.current);
                show(null, true);
            },
        };
    }, []);
    return (<TooltipContext.Provider value={api}>
      {children}
      {mounted
            ? artemisCreatePortal(<AnimatePresence custom={exitInstant}>{shown ? <Bubble key="bubble" shown={shown}/> : null}</AnimatePresence>, document.body)
            : null}
    </TooltipContext.Provider>);
}
export function ArtemisMorphicTooltip({ content, disabled = false, children, }: {
    content: string;
    disabled?: boolean;
    children: ReactNode;
}) {
    const api = useContext(TooltipContext);
    const key = useId();
    const ref = useRef<HTMLSpanElement>(null);
    useEffect(() => () => api?.hide(key), [api, key]);
    const anchor = useCallback(() => ref.current, []);
    return (<span ref={ref} className="art:inline-flex" onPointerEnter={(event) => {
            const el = anchor();
            if (!disabled && el && event.pointerType !== "touch")
                api?.enter(key, el, content);
        }} onPointerLeave={() => api?.leave(key)} onPointerDown={() => api?.down(key)} onFocus={(event) => {
            const el = anchor();
            if (!disabled && el && event.target instanceof Element && event.target.matches(":focus-visible")) {
                api?.focus(key, el, content);
            }
        }} onBlur={() => api?.blur(key)}>
      {children}
    </span>);
}

"use client";
// @zeus-internal
import { Bell, Check, CheckCheck, Search, X } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { type KeyboardEvent as ReactKeyboardEvent, type ReactNode, type RefObject, useId, useMemo, useRef, useState, } from "react";
import { PanelButton as ArtemisButton } from "./panel-button";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
import type { NotificationItem, PanelFilter } from "./data";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "./morphic-tooltip";
import { GroupHeading, NotificationRow } from "./notification-row";
import { MenuPortalContext } from "./row-menu";
const FOCUS = "art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
const INDICATOR_TRANSITION = { type: "spring", visualDuration: 0.44, bounce: 0.16 } as const;
const LIST_TRANSITION = { duration: 0.14, ease: ARTEMIS_EASE_OUT } as const;
const EMPTY_TRANSITION = { duration: 0.12, ease: "easeOut" } as const;
type Handlers = {
    onReadChange: (item: NotificationItem, read: boolean) => void;
    onMarkAllRead: () => void;
    onSnooze: (item: NotificationItem) => void;
    onArchive: (item: NotificationItem) => void;
    onSelect: (item: NotificationItem) => void;
};
function SearchField({ value, onChange, inputRef, }: {
    value: string;
    onChange: (value: string) => void;
    inputRef: RefObject<HTMLInputElement | null>;
}) {
    const id = useId();
    const [focused, setFocused] = useState(false);
    return (<div className="art:flex art:flex-col art:gap-1.5 art:w-full art:min-w-0 art:flex-1 art:mt-5">
      <div data-state={focused ? "focused" : "idle"} className={artemisCx("art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200", focused ? "art:border-foreground/60" : "art:border-border")}>
        <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
          <Search className="art:size-4" aria-hidden="true"/>
        </span>
        <input ref={inputRef} id={id} type="search" aria-label="Search notifications" placeholder="Search updates…" className={`art:peer art:h-full art:w-full art:bg-transparent art:text-foreground art:caret-foreground art:outline-none art:pl-10 ${value ? "art:pr-10" : "art:pr-3.5"} art:text-sm art:placeholder:text-muted-foreground`} value={value} onChange={(event) => onChange(event.target.value)} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}/>
        {value ? (<span className="art:absolute art:right-0 art:top-0 art:flex art:h-full art:items-center art:text-muted-foreground art:[&_button]:grid art:[&_button]:size-10 art:[&_button]:place-items-center art:[&_svg]:h-4 art:[&_svg]:w-4">
            <ArtemisMorphicTooltip content="Clear search">
              <ArtemisButton variant="ghost" size="icon" className={`art:size-9 ${FOCUS}`} aria-label="Clear search" onClick={() => {
                onChange("");
                inputRef.current?.focus();
            }}>
                <X className="art:size-3.5" aria-hidden="true"/>
              </ArtemisButton>
            </ArtemisMorphicTooltip>
          </span>) : null}
      </div>
      <div className="art:contents"/>
    </div>);
}
function FilterTabs({ tabs, value, onChange, baseId, }: {
    tabs: {
        id: string;
        label: string;
        count?: number;
    }[];
    value: string;
    onChange: (id: string) => void;
    baseId: string;
}) {
    const indicatorId = useId();
    const refs = useRef<(HTMLButtonElement | null)[]>([]);
    const onKeyDown = (event: ReactKeyboardEvent<HTMLButtonElement>, index: number) => {
        let next = -1;
        if (event.key === "ArrowRight")
            next = (index + 1) % tabs.length;
        else if (event.key === "ArrowLeft")
            next = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === "Home")
            next = 0;
        else if (event.key === "End")
            next = tabs.length - 1;
        if (next < 0)
            return;
        event.preventDefault();
        const tab = tabs[next];
        if (!tab)
            return;
        onChange(tab.id);
        refs.current[next]?.focus();
    };
    return (<div className="art:shrink-0 art:overflow-x-auto art:border-b art:border-border art:px-4 art:@min-[640px]/artemis:px-6">
      <div role="tablist" className="art:inline-flex art:items-center art:border-border art:w-max art:min-w-full art:gap-4 art:border-0" aria-label="Filter notifications">
        {tabs.map((tab, index) => {
            const selected = tab.id === value;
            return (<button key={tab.id} ref={(el) => {
                    refs.current[index] = el;
                }} type="button" role="tab" aria-selected={selected} className={artemisCx("art:relative art:isolate art:inline-flex art:items-center art:pt-1 art:pb-2.5 art:font-medium art:transition-colors", selected ? "art:text-foreground" : "art:text-muted-foreground art:hover:text-foreground", `art:mb-0 art:min-h-10 art:shrink-0 art:whitespace-nowrap art:rounded-md art:px-0 art:text-sm ${FOCUS}`)} id={`${baseId}-${tab.id}`} tabIndex={selected ? 0 : -1} aria-controls={`${baseId}-panel`} onClick={() => onChange(tab.id)} onKeyDown={(event) => onKeyDown(event, index)}>
              {tab.label}
              {tab.count ? <span className="art:ml-1.5 art:tabular-nums">{tab.count}</span> : null}
              {selected ? (<motion.span layoutId={indicatorId} layout="position" className="art:absolute art:right-0 art:left-0 art:bottom-0 art:h-0.5 art:bg-foreground" initial={false} animate={{ opacity: 1 }} transition={INDICATOR_TRANSITION}/>) : null}
            </button>);
        })}
      </div>
    </div>);
}
function EmptyState({ title, description, action }: {
    title: string;
    description: string;
    action: ReactNode;
}) {
    return (<motion.div className="art:flex art:h-full art:flex-col art:items-center art:justify-center art:gap-3 art:px-4 art:py-6 art:text-center" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={EMPTY_TRANSITION}>
      <span className="art:flex art:size-12 art:items-center art:justify-center art:rounded-full art:border art:border-border">
        <Check className="art:size-5 art:text-muted-foreground" aria-hidden="true"/>
      </span>
      <div>
        <p className="art:text-sm art:font-medium">{title}</p>
        <p className="art:mt-1 art:text-xs art:text-muted-foreground">{description}</p>
      </div>
      {action}
    </motion.div>);
}
function matches(item: NotificationItem, filter: string, query: string) {
    if (filter === "unread" && item.read)
        return false;
    if (filter !== "all" && filter !== "unread" && item.category !== filter)
        return false;
    if (!query)
        return true;
    return `${item.title} ${item.description}`.toLowerCase().includes(query);
}
export function NotificationPanel({ items, query, onQueryChange, filters, headerActions, footer, handlers, }: {
    items: readonly NotificationItem[];
    query: string;
    onQueryChange: (query: string) => void;
    filters: readonly PanelFilter[];
    headerActions?: ReactNode;
    footer?: ReactNode;
    handlers: Handlers;
}) {
    const titleId = useId();
    const tabsId = useId();
    const sectionRef = useRef<HTMLElement>(null);
    const searchRef = useRef<HTMLInputElement>(null);
    const [filter, setFilter] = useState("all");
    const unread = items.filter((item) => !item.read).length;
    const normalized = query.trim().toLowerCase();
    const visible = useMemo(() => items.filter((item) => matches(item, filter, normalized)), [items, filter, normalized]);
    const tabs = [
        { id: "all", label: "All" },
        ...filters.map((f) => ({ id: f.id, label: f.label, count: f.id === "unread" ? unread : undefined })),
    ];
    const rows: ReactNode[] = [];
    let group: string | null = null;
    for (const item of visible) {
        if (item.group !== group) {
            group = item.group;
            rows.push(<GroupHeading key={`art:group-${item.group}`} label={item.group}/>);
        }
        rows.push(<NotificationRow key={item.id} item={item} onReadChange={handlers.onReadChange} onSnooze={handlers.onSnooze} onArchive={handlers.onArchive} onSelect={handlers.onSelect}/>);
    }
    const clearSearch = () => {
        onQueryChange("");
        searchRef.current?.focus();
    };
    let empty: ReactNode = null;
    if (visible.length === 0) {
        empty = normalized ? (<EmptyState title="No matching updates" description="Try another search or clear it to see more updates." action={<ArtemisButton variant="tertiary" className={`art:h-9 art:px-4 art:text-xs ${FOCUS}`} onClick={clearSearch}>
            Clear search
          </ArtemisButton>}/>) : (<EmptyState title={filter === "unread" ? "You\u2019re all caught up" : "No notifications"} description="Your next update will appear here." action={filter === "all" ? null : (<ArtemisButton variant="tertiary" className={`art:h-9 art:px-4 art:text-xs ${FOCUS}`} onClick={() => setFilter("all")}>
              View all updates
            </ArtemisButton>)}/>);
    }
    return (<ArtemisMorphicTooltipProvider>
      <MenuPortalContext.Provider value={sectionRef}>
